<?php
declare(strict_types=1);

function sf_distribution_json(array $v): string { return json_encode($v,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE) ?: '{}'; }
function sf_distribution_decode(mixed $v,array $fallback=[]): array { $d=is_array($v)?$v:json_decode((string)$v,true); return is_array($d)?$d:$fallback; }
function sf_distribution_release_rows(): array {
    $path=SF_ROOT.'/data/releases.json';
    $rows=is_file($path)?json_decode((string)file_get_contents($path),true):[];
    return is_array($rows)?array_values($rows):[];
}
function sf_distribution_release(string $releaseId): ?array {
    foreach(sf_distribution_release_rows() as $r) if((string)($r['id']??'')===$releaseId) return $r;
    return null;
}
function sf_distribution_track(string $trackId): ?array {
    foreach(sf_catalog() as $t) if((string)($t['id']??'')===$trackId) return $t;
    return null;
}
function sf_distribution_normalize_isrc(string $v): string { return strtoupper(preg_replace('/[^A-Z0-9]/i','',$v)??''); }
function sf_distribution_valid_isrc(string $v): bool { $v=sf_distribution_normalize_isrc($v); return (bool)preg_match('/^[A-Z]{2}[A-Z0-9]{3}[0-9]{7}$/',$v); }
function sf_distribution_normalize_barcode(string $v): string { return preg_replace('/\D/','',$v)??''; }
function sf_distribution_valid_barcode(string $v): bool {
    $d=sf_distribution_normalize_barcode($v);$n=strlen($d);if(!in_array($n,[12,13],true))return false;
    $sum=0;$weight=3;for($i=$n-2;$i>=0;$i--){$sum+=((int)$d[$i])*$weight;$weight=$weight===3?1:3;}
    return ((10-($sum%10))%10)===(int)$d[$n-1];
}
function sf_distribution_destinations(): array { return ['spotify','apple_music','youtube_music','amazon_music','bandcamp']; }

function sf_distribution_ensure_schema(): void {
    static $done=false;if($done)return;$pdo=sf_db();$driver=(string)(sf_db_config()['driver']??'');
    if($driver==='sqlite'){
        $pdo->exec("CREATE TABLE IF NOT EXISTS distribution_releases (release_id TEXT PRIMARY KEY,distribution_state TEXT NOT NULL DEFAULT 'draft',primary_artist TEXT NOT NULL DEFAULT 'Stonefellow',version_title TEXT NOT NULL DEFAULT '',label TEXT NOT NULL DEFAULT '',genre TEXT NOT NULL DEFAULT '',subgenre TEXT NOT NULL DEFAULT '',language TEXT NOT NULL DEFAULT 'English',explicit INTEGER NOT NULL DEFAULT 0,territory TEXT NOT NULL DEFAULT 'worldwide',copyright_line TEXT NOT NULL DEFAULT '',phonographic_line TEXT NOT NULL DEFAULT '',upc_ean TEXT NOT NULL DEFAULT '',catalog_number TEXT NOT NULL DEFAULT '',metadata_json TEXT NOT NULL DEFAULT '{}',package_path TEXT NOT NULL DEFAULT '',package_sha256 TEXT NOT NULL DEFAULT '',package_built_at TEXT NULL,submitted_at TEXT NULL,scheduled_at TEXT NULL,live_at TEXT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL)");
        $pdo->exec("CREATE TABLE IF NOT EXISTS distribution_destinations (id INTEGER PRIMARY KEY AUTOINCREMENT,release_id TEXT NOT NULL,provider TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'not_started',external_id TEXT NOT NULL DEFAULT '',release_url TEXT NOT NULL DEFAULT '',notes TEXT NOT NULL DEFAULT '',submitted_at TEXT NULL,scheduled_at TEXT NULL,live_at TEXT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(release_id,provider),FOREIGN KEY(release_id) REFERENCES distribution_releases(release_id) ON DELETE CASCADE)");
        $pdo->exec("CREATE INDEX IF NOT EXISTS idx_distribution_destinations_release ON distribution_destinations(release_id,status)");
        $pdo->exec("CREATE TABLE IF NOT EXISTS distribution_events (id INTEGER PRIMARY KEY AUTOINCREMENT,release_id TEXT NOT NULL,event_type TEXT NOT NULL,detail_json TEXT NOT NULL DEFAULT '{}',admin_user_id INTEGER NULL,created_at TEXT NOT NULL,FOREIGN KEY(release_id) REFERENCES distribution_releases(release_id) ON DELETE CASCADE,FOREIGN KEY(admin_user_id) REFERENCES users(id) ON DELETE SET NULL)");
        $pdo->exec("CREATE INDEX IF NOT EXISTS idx_distribution_events_release ON distribution_events(release_id,id)");
    }else{
        $pdo->exec("CREATE TABLE IF NOT EXISTS distribution_releases (release_id VARCHAR(160) NOT NULL PRIMARY KEY,distribution_state VARCHAR(32) NOT NULL DEFAULT 'draft',primary_artist VARCHAR(220) NOT NULL DEFAULT 'Stonefellow',version_title VARCHAR(180) NOT NULL DEFAULT '',label VARCHAR(180) NOT NULL DEFAULT '',genre VARCHAR(100) NOT NULL DEFAULT '',subgenre VARCHAR(100) NOT NULL DEFAULT '',language VARCHAR(80) NOT NULL DEFAULT 'English',explicit TINYINT(1) NOT NULL DEFAULT 0,territory VARCHAR(120) NOT NULL DEFAULT 'worldwide',copyright_line VARCHAR(500) NOT NULL DEFAULT '',phonographic_line VARCHAR(500) NOT NULL DEFAULT '',upc_ean VARCHAR(32) NOT NULL DEFAULT '',catalog_number VARCHAR(100) NOT NULL DEFAULT '',metadata_json LONGTEXT NOT NULL,package_path VARCHAR(700) NOT NULL DEFAULT '',package_sha256 CHAR(64) NOT NULL DEFAULT '',package_built_at VARCHAR(40) NULL,submitted_at VARCHAR(40) NULL,scheduled_at VARCHAR(40) NULL,live_at VARCHAR(40) NULL,created_at VARCHAR(40) NOT NULL,updated_at VARCHAR(40) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
        $pdo->exec("CREATE TABLE IF NOT EXISTS distribution_destinations (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,release_id VARCHAR(160) NOT NULL,provider VARCHAR(60) NOT NULL,status VARCHAR(32) NOT NULL DEFAULT 'not_started',external_id VARCHAR(255) NOT NULL DEFAULT '',release_url VARCHAR(700) NOT NULL DEFAULT '',notes TEXT NOT NULL,submitted_at VARCHAR(40) NULL,scheduled_at VARCHAR(40) NULL,live_at VARCHAR(40) NULL,created_at VARCHAR(40) NOT NULL,updated_at VARCHAR(40) NOT NULL,UNIQUE KEY uq_distribution_destination(release_id,provider),INDEX idx_distribution_destinations_release(release_id,status),CONSTRAINT fk_distribution_destination_release FOREIGN KEY(release_id) REFERENCES distribution_releases(release_id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
        $pdo->exec("CREATE TABLE IF NOT EXISTS distribution_events (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,release_id VARCHAR(160) NOT NULL,event_type VARCHAR(80) NOT NULL,detail_json LONGTEXT NOT NULL,admin_user_id BIGINT UNSIGNED NULL,created_at VARCHAR(40) NOT NULL,INDEX idx_distribution_events_release(release_id,id),CONSTRAINT fk_distribution_event_release FOREIGN KEY(release_id) REFERENCES distribution_releases(release_id) ON DELETE CASCADE,CONSTRAINT fk_distribution_event_admin FOREIGN KEY(admin_user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    }
    $done=true;
}
function sf_distribution_event(string $releaseId,string $type,array $detail=[],int $adminId=0): void {
    sf_distribution_ensure_schema();$q=sf_db()->prepare('INSERT INTO distribution_events(release_id,event_type,detail_json,admin_user_id,created_at) VALUES(?,?,?,?,?)');$q->execute([$releaseId,$type,sf_distribution_json($detail),$adminId?:null,gmdate('c')]);
}
function sf_distribution_record(string $releaseId,bool $create=true): ?array {
    sf_distribution_ensure_schema();$q=sf_db()->prepare('SELECT * FROM distribution_releases WHERE release_id=?');$q->execute([$releaseId]);$r=$q->fetch();
    if(!$r&&$create){$release=sf_distribution_release($releaseId);if(!$release)return null;$r=sf_distribution_seed_release($release);}
    if(!$r)return null;$r['metadata']=sf_distribution_decode($r['metadata_json']??'',[]);
    $q=sf_db()->prepare('SELECT * FROM distribution_destinations WHERE release_id=? ORDER BY id');$q->execute([$releaseId]);$r['destinations']=$q->fetchAll();
    $q=sf_db()->prepare('SELECT * FROM distribution_events WHERE release_id=? ORDER BY id DESC LIMIT 100');$q->execute([$releaseId]);$events=$q->fetchAll();foreach($events as &$e)$e['detail']=sf_distribution_decode($e['detail_json']??'',[]);unset($e);$r['events']=$events;
    $r['readiness']=sf_distribution_release_readiness($releaseId,$r);return $r;
}
function sf_distribution_seed_release(array $release): array {
    sf_distribution_ensure_schema();$id=sf_clean_text($release['id']??'',160);if($id==='')throw new InvalidArgumentException('Release ID is required.');$q=sf_db()->prepare('SELECT release_id FROM distribution_releases WHERE release_id=?');$q->execute([$id]);if($q->fetchColumn())return sf_distribution_record($id,false)?:[];
    $now=gmdate('c');$year=(int)substr((string)($release['release_date']??gmdate('Y')),0,4);if($year<1900||$year>2100)$year=(int)gmdate('Y');
    $label=sf_clean_text($release['label']??'',180);$genre=sf_clean_text($release['genre']??'',100);$upc=sf_distribution_normalize_barcode((string)($release['upc_ean']??''));$catalog=sf_clean_text($release['catalog_number']??'',100);
    $q=sf_db()->prepare("INSERT INTO distribution_releases(release_id,distribution_state,primary_artist,version_title,label,genre,subgenre,language,explicit,territory,copyright_line,phonographic_line,upc_ean,catalog_number,metadata_json,created_at,updated_at) VALUES(?,'draft','Stonefellow','',?,?,'','English',0,'worldwide',?,?,?,?,'{}',?,?)");
    $q->execute([$id,$label,$genre,'© '.$year.' '.($label?:'Stonefellow'),'℗ '.$year.' '.($label?:'Stonefellow'),$upc,$catalog,$now,$now]);
    foreach(sf_distribution_destinations() as $provider){$s=sf_db()->prepare("INSERT INTO distribution_destinations(release_id,provider,status,external_id,release_url,notes,created_at,updated_at) VALUES(?,?,'not_started','','','',?,?)");$s->execute([$id,$provider,$now,$now]);}
    sf_distribution_event($id,'distribution_initialized',['source'=>'release_backfill']);return sf_distribution_record($id,false)?:[];
}
function sf_distribution_backfill(): array {
    sf_distribution_ensure_schema();$added=0;$existing=0;foreach(sf_distribution_release_rows() as $r){$id=(string)($r['id']??'');if($id==='')continue;$q=sf_db()->prepare('SELECT 1 FROM distribution_releases WHERE release_id=?');$q->execute([$id]);if($q->fetchColumn()){$existing++;continue;}sf_distribution_seed_release($r);$added++;}return ['added'=>$added,'existing'=>$existing];
}
function sf_distribution_media_for(string $entityType,string $entityId,array $roles): ?array {
    if(!function_exists('sf_media_ensure_schema'))return null;sf_media_ensure_schema();$sql='SELECT l.*,a.uuid,a.category,a.mime_type,a.extension,a.original_name,a.stored_path,a.sha256,a.size_bytes,a.width,a.height,a.duration_seconds,a.sample_rate_hz,a.channels,a.bits_per_sample,a.codec FROM media_links l JOIN media_assets a ON a.id=l.asset_id WHERE l.entity_type=? AND l.entity_id=?';$args=[$entityType,$entityId];
    if($roles){$sql.=' AND l.role IN ('.implode(',',array_fill(0,count($roles),'?')).')';$args=array_merge($args,$roles);}$sql.=' ORDER BY l.featured DESC,l.id DESC LIMIT 1';$q=sf_db()->prepare($sql);$q->execute($args);return $q->fetch()?:null;
}
function sf_distribution_add_check(array &$checks,string $key,string $label,bool $ok,string $severity,string $detail): void {$checks[]=['key'=>$key,'label'=>$label,'ok'=>$ok,'severity'=>$severity,'detail'=>$detail];}
function sf_distribution_release_readiness(string $releaseId,?array $record=null): array {
    $release=sf_distribution_release($releaseId);if(!$release)return ['ready'=>false,'score'=>0,'checks'=>[],'blockers'=>['Release not found.'],'warnings'=>[],'tracks'=>[]];
    if($record===null){sf_distribution_ensure_schema();$q=sf_db()->prepare('SELECT * FROM distribution_releases WHERE release_id=?');$q->execute([$releaseId]);$record=$q->fetch()?:[];}
    $checks=[];$blockers=[];$warnings=[];$tracks=[];$title=trim((string)($release['title']??''));$date=trim((string)($release['release_date']??''));
    sf_distribution_add_check($checks,'title','Release title',$title!=='','blocker',$title!==''?$title:'Release title is missing.');
    $artist=trim((string)($record['primary_artist']??''));sf_distribution_add_check($checks,'artist','Primary artist',$artist!=='','blocker',$artist!==''?$artist:'Primary artist is missing.');
    $dateOk=$date!==''&&strtotime($date)!==false;sf_distribution_add_check($checks,'release_date','Release date',$dateOk,'blocker',$dateOk?$date:'Release date is missing or invalid.');
    foreach(['label'=>'Label','genre'=>'Genre','language'=>'Language','territory'=>'Territory'] as $k=>$label){$v=trim((string)($record[$k]??($release[$k]??'')));sf_distribution_add_check($checks,$k,$label,$v!=='','blocker',$v!==''?$v:$label.' is missing.');}
    $barcode=sf_distribution_normalize_barcode((string)($record['upc_ean']??($release['upc_ean']??'')));$barOk=sf_distribution_valid_barcode($barcode);sf_distribution_add_check($checks,'upc_ean','UPC / EAN',$barOk,'blocker',$barOk?$barcode:'A valid UPC-A (12 digit) or EAN-13 barcode is required.');
    $cat=trim((string)($record['catalog_number']??($release['catalog_number']??'')));sf_distribution_add_check($checks,'catalog_number','Catalog number',$cat!=='','warning',$cat!==''?$cat:'Catalog number is blank.');
    foreach(['copyright_line'=>'© composition copyright','phonographic_line'=>'℗ master copyright'] as $k=>$label){$v=trim((string)($record[$k]??''));sf_distribution_add_check($checks,$k,$label,$v!=='','blocker',$v!==''?$v:$label.' is missing.');}
    $cover=sf_distribution_media_for('release',$releaseId,['cover']);$legacyCover=trim((string)($release['artwork']['cover']??''));$coverExists=$cover!==null||$legacyCover!=='';sf_distribution_add_check($checks,'cover','Front cover',$coverExists,'blocker',$coverExists?'Cover assigned.':'Front cover is missing.');
    if($cover){$resOk=(int)$cover['width']>=3000&&(int)$cover['height']>=3000;sf_distribution_add_check($checks,'cover_resolution','Cover resolution',$resOk,'blocker',$resOk?((int)$cover['width'].'×'.(int)$cover['height']):'Managed cover must be at least 3000×3000.');}
    elseif($legacyCover!=='')sf_distribution_add_check($checks,'cover_resolution','Cover resolution',false,'warning','Cover exists outside the managed Media Library; resolution cannot be certified.');
    $trackIds=array_values((array)($release['track_ids']??[]));sf_distribution_add_check($checks,'tracks','Track list',count($trackIds)>0,'blocker',count($trackIds).' track(s).');
    foreach($trackIds as $tid){$tid=(string)$tid;$t=sf_distribution_track($tid)?:[];$m=(array)($t['metadata']??[]);$isrc=sf_distribution_normalize_isrc((string)($m['isrc']??''));$audio=sf_distribution_media_for('track',$tid,['master_audio','primary_audio']);$legacyAudio=trim((string)($t['audio']??''));$audioOk=$audio!==null||$legacyAudio!=='';$wav=$audio?strtolower((string)$audio['extension'])==='wav':str_ends_with(strtolower(parse_url($legacyAudio,PHP_URL_PATH)?:$legacyAudio),'.wav');$duration=$audio?(float)$audio['duration_seconds']:(float)($t['duration']??0);
        $tr=['track_id'=>$tid,'title'=>(string)($t['title']??$tid),'isrc'=>$isrc,'isrc_valid'=>sf_distribution_valid_isrc($isrc),'audio_ready'=>$audioOk,'wav_master'=>$wav,'duration'=>$duration,'asset'=>$audio];
        if(!$tr['isrc_valid'])$blockers[]=$tr['title'].': valid ISRC required.';if(!$audioOk)$blockers[]=$tr['title'].': master audio is missing.';elseif(!$wav)$warnings[]=$tr['title'].': distributor package should use a WAV master.';if($duration<=0)$warnings[]=$tr['title'].': audio duration is unknown.';$tracks[]=$tr;
    }
    if($trackIds){$allIsrc=count(array_filter($tracks,fn($t)=>$t['isrc_valid']))===count($tracks);sf_distribution_add_check($checks,'isrc','Track ISRCs',$allIsrc,'blocker',$allIsrc?'All track ISRCs valid.':'One or more tracks need a valid ISRC.');$allAudio=count(array_filter($tracks,fn($t)=>$t['audio_ready']))===count($tracks);sf_distribution_add_check($checks,'masters','Audio masters',$allAudio,'blocker',$allAudio?'All tracks have audio.':'One or more tracks are missing audio.');}
    if(function_exists('sf_rights_release_readiness')){$rights=sf_rights_release_readiness($releaseId);$rightsOk=!empty($rights['ready']);sf_distribution_add_check($checks,'rights','Rights + licensing',$rightsOk,'blocker',$rightsOk?'Rights clearance ready.':implode(' · ',array_slice((array)$rights['blockers'],0,4)));if(!$rightsOk)$blockers=array_merge($blockers,(array)$rights['blockers']);$warnings=array_merge($warnings,(array)($rights['warnings']??[]));}
    foreach($checks as $c){if(!$c['ok']){if($c['severity']==='blocker')$blockers[]=$c['detail'];else$warnings[]=$c['detail'];}}
    $passed=count(array_filter($checks,fn($c)=>!empty($c['ok'])));$score=count($checks)?(int)round($passed*100/count($checks)):0;
    return ['release_id'=>$releaseId,'title'=>$title?:$releaseId,'ready'=>count(array_unique($blockers))===0,'score'=>$score,'checks'=>$checks,'blockers'=>array_values(array_unique($blockers)),'warnings'=>array_values(array_unique($warnings)),'tracks'=>$tracks];
}
function sf_distribution_save_metadata(string $releaseId,array $raw,int $adminId=0): array {
    $rec=sf_distribution_record($releaseId);if(!$rec)throw new InvalidArgumentException('Release not found.');$barcode=sf_distribution_normalize_barcode((string)($raw['upc_ean']??$rec['upc_ean']??''));if($barcode!==''&&!sf_distribution_valid_barcode($barcode))throw new InvalidArgumentException('UPC/EAN checksum is invalid.');
    $now=gmdate('c');$vals=[sf_clean_text($raw['primary_artist']??$rec['primary_artist']??'Stonefellow',220),sf_clean_text($raw['version_title']??$rec['version_title']??'',180),sf_clean_text($raw['label']??$rec['label']??'',180),sf_clean_text($raw['genre']??$rec['genre']??'',100),sf_clean_text($raw['subgenre']??$rec['subgenre']??'',100),sf_clean_text($raw['language']??$rec['language']??'English',80),!empty($raw['explicit'])?1:0,sf_clean_text($raw['territory']??$rec['territory']??'worldwide',120),sf_clean_text($raw['copyright_line']??$rec['copyright_line']??'',500),sf_clean_text($raw['phonographic_line']??$rec['phonographic_line']??'',500),$barcode,sf_clean_text($raw['catalog_number']??$rec['catalog_number']??'',100),sf_distribution_json((array)($raw['metadata']??$rec['metadata']??[])),$now,$releaseId];
    sf_db()->prepare('UPDATE distribution_releases SET primary_artist=?,version_title=?,label=?,genre=?,subgenre=?,language=?,explicit=?,territory=?,copyright_line=?,phonographic_line=?,upc_ean=?,catalog_number=?,metadata_json=?,updated_at=? WHERE release_id=?')->execute($vals);sf_distribution_event($releaseId,'metadata_saved',[], $adminId);return sf_distribution_record($releaseId)?:[];
}
function sf_distribution_set_state(string $releaseId,string $state,int $adminId=0): array {
    $allowed=['draft','preparing','ready','submitted','scheduled','live','archived'];if(!in_array($state,$allowed,true))throw new InvalidArgumentException('Invalid distribution state.');$rec=sf_distribution_record($releaseId);if(!$rec)throw new InvalidArgumentException('Release not found.');
    if(in_array($state,['ready','submitted','scheduled','live'],true)){ $read=sf_distribution_release_readiness($releaseId,$rec);if(empty($read['ready']))throw new RuntimeException('Release is blocked: '.implode(' ',array_slice($read['blockers'],0,5))); }
    $now=gmdate('c');$submitted=$rec['submitted_at']??null;$scheduled=$rec['scheduled_at']??null;$live=$rec['live_at']??null;if($state==='submitted'&&!$submitted)$submitted=$now;if($state==='scheduled'&&!$scheduled)$scheduled=$now;if($state==='live'&&!$live)$live=$now;
    sf_db()->prepare('UPDATE distribution_releases SET distribution_state=?,submitted_at=?,scheduled_at=?,live_at=?,updated_at=? WHERE release_id=?')->execute([$state,$submitted,$scheduled,$live,$now,$releaseId]);sf_distribution_event($releaseId,'state_changed',['from'=>$rec['distribution_state'],'to'=>$state],$adminId);return sf_distribution_record($releaseId)?:[];
}
function sf_distribution_save_destination(string $releaseId,array $raw,int $adminId=0): array {
    $provider=sf_clean_text($raw['provider']??'',60);if(!in_array($provider,sf_distribution_destinations(),true))throw new InvalidArgumentException('Unsupported destination.');$status=(string)($raw['status']??'not_started');$allowed=['not_started','preparing','submitted','scheduled','live','failed'];if(!in_array($status,$allowed,true))throw new InvalidArgumentException('Invalid destination status.');
    $rec=sf_distribution_record($releaseId);if(!$rec)throw new InvalidArgumentException('Release not found.');if(in_array($status,['submitted','scheduled','live'],true)&&empty($rec['readiness']['ready']))throw new RuntimeException('Resolve release blockers before marking a destination '.$status.'.');
    $q=sf_db()->prepare('SELECT * FROM distribution_destinations WHERE release_id=? AND provider=?');$q->execute([$releaseId,$provider]);$old=$q->fetch()?:[];$now=gmdate('c');$submitted=$old['submitted_at']??null;$scheduled=$old['scheduled_at']??null;$live=$old['live_at']??null;if($status==='submitted'&&!$submitted)$submitted=$now;if($status==='scheduled'&&!$scheduled)$scheduled=$now;if($status==='live'&&!$live)$live=$now;
    sf_db()->prepare('UPDATE distribution_destinations SET status=?,external_id=?,release_url=?,notes=?,submitted_at=?,scheduled_at=?,live_at=?,updated_at=? WHERE release_id=? AND provider=?')->execute([$status,sf_clean_text($raw['external_id']??'',255),sf_clean_text($raw['release_url']??'',700),sf_clean_text($raw['notes']??'',5000),$submitted,$scheduled,$live,$now,$releaseId,$provider]);sf_distribution_event($releaseId,'destination_updated',['provider'=>$provider,'status'=>$status],$adminId);return sf_distribution_record($releaseId)?:[];
}
function sf_distribution_sync_calendar(string $releaseId,int $adminId=0): array {
    if(!function_exists('sf_calendar_ensure_schema'))throw new RuntimeException('Operating Calendar is unavailable.');$release=sf_distribution_release($releaseId);if(!$release)throw new InvalidArgumentException('Release not found.');$target=(string)($release['release_date']??'');if($target===''||strtotime($target)===false)throw new RuntimeException('Set a release date before synchronizing the calendar.');sf_calendar_ensure_schema();
    $q=sf_db()->prepare("SELECT id FROM operating_plans WHERE primary_entity_type='release' AND primary_entity_id=? AND status<>'archived' ORDER BY id LIMIT 1");$q->execute([$releaseId]);$planId=(int)($q->fetchColumn()?:0);
    if(!$planId){$p=sf_calendar_save_plan(['name'=>'Release — '.($release['title']??$releaseId),'plan_type'=>'single_release','status'=>'active','target_at'=>$target,'timezone'=>'America/Phoenix','primary_entity_type'=>'release','primary_entity_id'=>$releaseId,'notes'=>'Synced from Distribution Operations.','skip_template'=>true],$adminId);$planId=(int)$p['id'];}
    $defs=[['distribution_submission',-28,'Distributor submission deadline','distribution_submission',1],['presave',-21,'Presave / pre-add opens','presave',0],['campaign_start',-14,'Release campaign start','campaign',0],['release_day',0,'Release day / DSP live check','launch',1]];$added=0;$updated=0;
    foreach($defs as [$key,$offset,$title,$type,$blocking]){$entity='distribution:'.$releaseId.':'.$key;$due=sf_calendar_shift($target,$offset);$q=sf_db()->prepare("SELECT id FROM operating_milestones WHERE plan_id=? AND entity_type='distribution' AND entity_id=? LIMIT 1");$q->execute([$planId,$entity]);$id=(int)($q->fetchColumn()?:0);if($id){sf_calendar_save_milestone(['id'=>$id,'plan_id'=>$planId,'title'=>$title,'milestone_type'=>$type,'due_at'=>$due,'status'=>'pending','priority'=>'high','blocking'=>$blocking,'entity_type'=>'distribution','entity_id'=>$entity,'offset_days'=>$offset]);$updated++;}else{sf_calendar_save_milestone(['plan_id'=>$planId,'title'=>$title,'milestone_type'=>$type,'due_at'=>$due,'status'=>'pending','priority'=>'high','blocking'=>$blocking,'entity_type'=>'distribution','entity_id'=>$entity,'offset_days'=>$offset]);$added++;}}
    sf_distribution_event($releaseId,'calendar_synced',['plan_id'=>$planId,'added'=>$added,'updated'=>$updated],$adminId);return ['plan'=>sf_calendar_plan($planId),'added'=>$added,'updated'=>$updated];
}
function sf_distribution_build_manifest(string $releaseId): array {
